import path from 'node:path';
import {fileURLToPath} from 'node:url';
import dotenv from 'dotenv';
import type {FastifyInstance} from 'fastify';
import pg from 'pg';
import {afterAll, beforeAll, describe, expect, it} from 'vitest';
import {buildApp} from '../app.js';
import {gazePoolConfig} from '../db/gaze-db.js';
import {runMigrations} from '../db/migrations.js';
import {requirePage, SESSION_COOKIE} from '../plugins/auth.js';

const here = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({path: path.join(here, '..', '..', '..', '.env'), quiet: true});

// Generated by the Python app's hash_profile_password('correct horse ünïcode').
const PYTHON_HASH = 'pbkdf2_sha256$0ce2722220d400e18c2134109203b6f2$80b3a18caace9e01865172c609811d8392d0696a0aaf19a716e685635b709eec';
const PASSWORD = 'correct horse ünïcode';

describe.skipIf(!process.env.GAZE_DATABASE_URL)('auth routes', () => {
    const schema = `test_auth_${process.pid}`;
    const pool = new pg.Pool({...gazePoolConfig(process.env.GAZE_DATABASE_URL ?? ''), options: `-c search_path=${schema}`, max: 3});
    let app: FastifyInstance;

    beforeAll(async () => {
        await pool.query(`CREATE SCHEMA ${schema}`);
        await runMigrations(pool);
        await pool.query(
            `INSERT INTO users (key, name, title, role, username, password_hash, allowed_routes) VALUES
             ('damian', 'Damian', 'CEO', 'viewer', 'damian', $1, '{/c-hub/revenue}'),
             ('nopass', 'No Pass', '', 'viewer', 'nopass', NULL, '{*}')`,
            [PYTHON_HASH],
        );
        app = await buildApp({gazePool: pool});
        // Two page-data routes to check viewer permissions.
        app.get('/api/test/revenue', {preHandler: requirePage('/c-hub/revenue')}, async () => ({ok: true}));
        app.get('/api/test/commissions', {preHandler: requirePage('/c-hub/commissions')}, async () => ({ok: true}));
    });

    afterAll(async () => {
        await app?.close();
        await pool.query(`DROP SCHEMA IF EXISTS ${schema} CASCADE`);
        await pool.end();
    });

    async function login(username: string, password: string) {
        return app.inject({method: 'POST', url: '/api/auth/login', payload: {username, password}});
    }

    it('rejects API calls without a session', async () => {
        expect((await app.inject({url: '/api/auth/me'})).statusCode).toBe(401);
    });

    it('rejects a wrong password and a user without a password', async () => {
        expect((await login('damian', 'wrong')).statusCode).toBe(401);
        expect((await login('nopass', '')).statusCode).toBe(401);
        expect((await login('nopass', 'anything')).statusCode).toBe(401);
    });

    it('logs in with a Python-app password by key, username or name in any case', async () => {
        for (const name of ['damian', 'DAMIAN', ' Damian ']) {
            expect((await login(name, PASSWORD)).statusCode).toBe(200);
        }
    });

    it('serves the session user, enforces page access and logs out', async () => {
        const res = await login('damian', PASSWORD);
        const cookie = res.cookies.find(c => c.name === SESSION_COOKIE);
        expect(cookie?.httpOnly).toBe(true);
        const headers = {cookie: `${SESSION_COOKIE}=${cookie?.value}`};

        const me = await app.inject({url: '/api/auth/me', headers});
        expect(me.json().user).toMatchObject({key: 'damian', role: 'viewer', allowedRoutes: ['/c-hub/revenue']});
        expect(me.body).not.toContain('pbkdf2');

        expect((await app.inject({url: '/api/test/revenue', headers})).statusCode).toBe(200);
        expect((await app.inject({url: '/api/test/commissions', headers})).statusCode).toBe(404);

        expect((await app.inject({method: 'POST', url: '/api/auth/logout', headers})).statusCode).toBe(204);
        expect((await app.inject({url: '/api/auth/me', headers})).statusCode).toBe(401);
    });

    it('blocks a login name after 10 failures', async () => {
        for (let i = 0; i < 10; i++) await login('blocked-user', 'wrong');
        expect((await login('blocked-user', 'wrong')).statusCode).toBe(429);
    });
});
